def load() -> pd.DataFrame:
    import pandas as pd
    # Try common encodings for NOAA-provided CSVs
    try:
        return pd.read_csv('data/wildfire/input/noaa_wildfires_variabledescrip.csv', encoding='utf-8')
    except UnicodeDecodeError:
        try:
            return pd.read_csv('data/wildfire/input/noaa_wildfires_variabledescrip.csv', encoding='latin-1')
        except UnicodeDecodeError:
            return pd.read_csv('data/wildfire/input/noaa_wildfires_variabledescrip.csv', encoding='cp1252')

