def process(q1_months_known):
    import pandas as pd
    ct = pd.crosstab(q1_months_known['region'], q1_months_known['cause'])
    ct = ct.sort_index().reindex(sorted(ct.columns), axis=1)
    return ct.reset_index().rename(columns={'index':'region'})
